from collections import deque

def bfs_min(n,s,t, goal_any=False):
    start = tuple(list(s) + ['_','_'])
    target_seq = tuple(list(t))
    def is_goal(state):
        if not goal_any:
            if state[n] != '_' or state[n+1] != '_':
                return False
            return tuple(state[:n]) == target_seq
        else:
            seq = tuple(c for c in state if c != '_')
            return seq == target_seq
    visited = {start:0}
    q=deque([start])
    while q:
        cur=q.popleft()
        d=visited[cur]
        if is_goal(cur):
            return d
        # find gap
        g=None
        for i in range(n+1):
            if cur[i]=='_' and cur[i+1]=='_':
                g=i
                break
        for i in range(n+1):
            if cur[i]!='_' and cur[i+1]!='_':
                # need gap not overlapping
                # check i,i+1 not contain gap
                if i==g or i+1==g or i==g+1 or i+1==g+1:
                    continue
                # but our earlier check cur[i]!='_' ensures
                new=list(cur)
                new[g]=cur[i]
                new[g+1]=cur[i+1]
                new[i]='_'
                new[i+1]='_'
                nt=tuple(new)
                if nt not in visited:
                    visited[nt]=d+1
                    q.append(nt)
    return None

def test_explore():
    cases = [
     (4,'WWBB','BBWW'),
     (4,'BBWW','WWBB'),
    ]
    for n,s,t in cases:
        ge=bfs_min(n,s,t,False)
        ag=bfs_min(n,s,t,True)
        print(f"{s}->{t} gap_end={ge} any_gap={ag}")
    # also others
    print(bfs_min(6,'BWBWBW','WWWBBB',False), bfs_min(6,'BWBWBW','WWWBBB',True))
    print(bfs_min(4,'WWBB','WBWB',False), bfs_min(4,'WWBB','WBWB',True))
    print(bfs_min(6,'BBBBBB','WWWWWW',False), bfs_min(6,'BBBBBB','WWWWWW',True))
    assert False  # to show output

from collections import deque

def find_path(n,s,t):
    start = tuple(list(s) + ['_','_'])
    target = tuple(list(t) + ['_','_'])
    visited={start:None}
    q=deque([start])
    parent={start:None}
    while q:
        cur=q.popleft()
        if cur==target:
            break
        g=None
        for i in range(n+1):
            if cur[i]=='_' and cur[i+1]=='_':
                g=i
                break
        for i in range(n+1):
            if cur[i]!='_' and cur[i+1]!='_':
                if i==g: continue
                new=list(cur)
                new[g]=cur[i]
                new[g+1]=cur[i+1]
                new[i]='_'
                new[i+1]='_'
                nt=tuple(new)
                if nt not in visited:
                    visited[nt]=cur
                    parent[nt]=cur
                    q.append(nt)
    cur=target
    path=[]
    while cur is not None:
        path.append(cur)
        cur= parent.get(cur)
    path=path[::-1]
    for p in path:
        print(''.join(p))
    print("steps",len(path)-1)

def test_path():
    for n,s,t in [(4,'BBWW','WWBB'),(4,'WWBB','BBWW')]:
        print(f"\n=== {s}->{t} ===")
        find_path(n,s,t)
    assert False

