import math, sys, time

def rev_num(x):
    return int(str(x)[::-1])
def gen_x(limit):
    xs=[]
    q=deque([1,2,3,4,5,6,7,8,9])
    while q:
        x=q.popleft()
        if x>limit:
            continue
        xs.append(x)
        for d in range(1,10):
            nx=x*10+d
            if nx<=limit:
                q.append(nx)
    return xs
def gen_q_map(limit_q, limit_x):
    xs=gen_x(limit_x)
    q_to_x={}
    for x in xs:
        r=rev_num(x)
        q=x*r
        if q<=limit_q:
            if q not in q_to_x:
                q_to_x[q]=x
    return q_to_x, xs
def is_pal_19(n):
    s=str(n)
    if '0' in s:
        return False
    return s==s[::-1]

def can_decompose(n, q_to_x, verbose=False):
    qs = list(q_to_x.keys())
    memo={}
    qs_sorted=sorted(qs, reverse=True)
    count_calls=0
    def dfs(m):
        nonlocal count_calls
        count_calls+=1
        if m in memo:
            return memo[m]
        if is_pal_19(m):
            memo[m]= (True, [])
            return memo[m]
        for q in qs_sorted:
            if q>m: continue
            if q==1: continue
            if m % q !=0: continue
            nxt=m//q
            res = dfs(nxt)
            if res[0]:
                x=q_to_x[q]
                memo[m]= (True, [(q,x)]+res[1])
                return memo[m]
        memo[m]=(False, None)
        return memo[m]
    start=time.time()
    result=dfs(n)
    elapsed=time.time()-start
    if verbose:
        print(f"n={n} result={result[0]} calls={count_calls} time={elapsed:.2f}s memo size={len(memo)}")
        if result[0]:
            prod=1
            for qq,_ in result[1]:
                prod*=qq
            p=n//prod if result[1] else n
            print("p", p, "is_pal_19", is_pal_19(p), "path", result[1][:20])
    return result

def test_invalid():
    limit_q=10**12
