# caches for L and S
_LS_cache = {}

def _ls(n: int):
    """return (L(n), S(n)) for n >=0 . L(n)=total number of elements in big_nums for i=1..n, S(n)= sum of exponents k"""
    if n <= 0:
        return (0, 0)
    if n in _LS_cache:
        return _LS_cache[n]
    k = n.bit_length() - 1
    pow2k = 1 << k
    if k == 0:
        L_prev = 0
        S_prev = 0
    else:
        L_prev = k * (pow2k >> 1)
        S_prev = (pow2k >> 1) * k * (k - 1) // 2
    r = n - pow2k
    Lr, Sr = _ls(r)
    res = (L_prev + (r + 1) + Lr, S_prev + (r + 1) * k + Sr)
    _LS_cache[n] = res
    return res

def _L(n: int) -> int:
    if n < 0:
        return 0
    return _ls(n)[0]

def _S(n: int) -> int:
    if n < 0:
        return 0
    return _ls(n)[1]

def _bits_of(x: int):
    b = []
    while x:
        low = x & -x
        k = (low.bit_length() - 1)
        b.append(k)
        x ^= low
    return b  # already sorted ascending because lowbit

def _prefix_exp(N: int) -> int:
    """ sum_{idx=0..N} exponent k where big_nums[idx]=2^k . N can be -1 =>0"""
    if N < 0:
        return 0
    # binary search i = smallest with L(i) > N
    # L is monotonic
    lo = 0
    hi = 1 << 50  # > enough
    # ensure hi is enough
    # quickly increase if needed (should be enough for N up to 1e15, hi 1<<50 ~1e15, L(hi) huge ~ hi*25 ~2.5e16 >1e15)
    # but just in case
    while _L(hi) <= N:
        hi <<= 1
    while lo < hi:
        mid = (lo + hi) // 2
        if _L(mid) <= N:
            lo = mid + 1
        else:
            hi = mid
    i = lo
    prev_L = _L(i - 1)
    prev_S = _S(i - 1)
    offset = N - prev_L  # 0-indexed inside bits_of(i)
    b = _bits_of(i)
    # sum first offset+1 bits
    partial = sum(b[: offset + 1])
    return prev_S + partial

