def brute(n, edges):
    best=-1
    verts=list(range(1,n+1))
    for r in range(1,n+1):
        for comb in itertools.combinations(verts,r):
            s=set(comb)
            edge_cnt=0
            deg={v:0 for v in s}
            for a,b in edges:
                if a in s and b in s:
                    edge_cnt+=1
                    deg[a]+=1
                    deg[b]+=1
            if edge_cnt!=len(s)-1:
                continue
            if len(s)==1:
                continue
            has4=False
            ok=True
            for v in s:
                d=deg[v]
                if d==4:
                    has4=True
                elif d==1:
                    pass
                else:
                    ok=False
                    break
            if not ok or not has4:
                continue
            best=max(best,len(s))
    return best

