from functools import lru_cache

def dp_upto(X, lim, ss):
    if X < 0:
        return 0
    if any(int(d)>lim for d in ss):
        return 0
    xs = str(X)
    m = len(xs)
    n = len(ss)
    total=0
    for L in range(n, m):
        p=L-n
        if p==0:
            total+=1
        else:
            total+= lim * pow(lim+1, p-1)
    p=m-n
    if p<0:
        return total
    if p==0:
        if ss <= xs:
            total+=1
        return total
    s_digits=list(map(int, ss))
    @lru_cache(None)
    def dfs(pos, tight):
        if pos==m:
            return 1
        if pos < p:
            low=1 if pos==0 else 0
            up = int(xs[pos]) if tight else 9
            ans=0
            for d in range(low, min(lim, up)+1):
                ntight = tight and (d == int(xs[pos]))
                ans+= dfs(pos+1, ntight)
            return ans
        else:
            d_needed = s_digits[pos-p]
            up = int(xs[pos]) if tight else 9
            if d_needed > up:
                return 0
            ntight = tight and (d_needed == int(xs[pos]))
            return dfs(pos+1, ntight)
    total+= dfs(0, True)
    return total

def dp_range(start,finish,lim,ss):
    if any(int(d)>lim for d in ss):
        return 0
    return dp_upto(finish,lim,ss)-dp_upto(start-1,lim,ss)

