def inclusion_check(s):
    N=len(s)
    cand=[k for k in range(1,N) if s[:k].count('W')-s[:k].count('B')>=0]
    vals={}
    for k in cand+[N]:
        total=W(0,k,s)
        sub=sum(vals[prev]*W(prev,k,s) for prev in cand if prev<k and prev in vals)
        vals[k]=total-sub
    return vals[N]

