def brute(nums, k, limit):
    n=len(nums)
    best=-1
    for mask in range(1, 1<<n):
        seq=[]
        for i in range(n):
            if mask>>i &1:
                seq.append(nums[i])
        s=0
        for idx,val in enumerate(seq):
            s+= val if idx%2==0 else -val
        if s!=k:
            continue
        prod=1
        for v in seq:
            prod*=v
        if prod>limit:
            continue
        if prod>best:
            best=prod
    return best

