from typing import List, Tuple

def brute(n,h,w,tiles):
    N=len(tiles)
    H,W=h,w
    num_cells=H*W
    full_mask=(1<<num_cells)-1
    areas=[a*b for a,b in tiles]
    # placements per tile
    placements_by_cell=[[] for _ in range(num_cells)]
    all_masks=[]
    for idx,(a,b) in enumerate(tiles):
        seen=set()
        ors={(a,b),(b,a)}
        masks=set()
        for ta,tb in ors:
            if ta>H or tb>W:
                continue
            for r in range(H-ta+1):
                for c in range(W-tb+1):
                    m=0
                    for dr in range(ta):
                        base=(r+dr)*W+c
                        for dc in range(tb):
                            cell=base+dc
                            m|=1<<cell
                    if m not in seen:
                        seen.add(m)
                        masks.add(m)
                    # also add to per cell
        # for each mask, add to placements_by_cell
        for m in masks:
            all_masks.append((idx,m))
            # add to each cell
            # iterate cells in mask
            # for each cell bit
            tmp=m
            while tmp:
                lsb=tmp & -tmp
                c=(lsb.bit_length()-1)
                placements_by_cell[c].append((idx,m))
                tmp ^= lsb
    for lst in placements_by_cell:
        lst.sort(key=lambda x: -areas[x[0]])
    from functools import lru_cache
    # lru_cache needs hashable; use recursion
    import sys
    sys.setrecursionlimit(10000)
    def popcount(x):
        return bin(x).count("1")
    group_keys=[(min(a,b),max(a,b)) for a,b in tiles]
    groups={}
    for i,k in enumerate(group_keys):
        groups.setdefault(k,[]).append(i)
    group_lists=list(groups.values())
    def allowed_mask(used):
        mask=0
        for gl in group_lists:
            for idx in gl:
                if not (used>>idx)&1:
                    mask|=1<<idx
                    break
        return mask

    def subset_possible(rem, used):
        if rem==0:
            return True
        ach=1
        for i in range(N):
            if not (used>>i)&1:
                ach|=ach<<areas[i]
                if (ach>>rem)&1:
                    return True
        return (ach>>rem)&1==1

    visited=set()
    memo={}
    @lru_cache(maxsize=None)
    def dfs(occ, used):
        if occ==full_mask:
            return True
        rem=num_cells - popcount(occ)
        if not subset_possible(rem, used):
            return False
        # first empty
        rembits=full_mask ^ occ
        lsb=rembits & -rembits
        first=(lsb.bit_length()-1)
        cands=placements_by_cell[first]
        if not cands:
            return False
        allowed=allowed_mask(used)
        for idx,m in cands:
            if (used>>idx)&1: continue
            if not (allowed>>idx)&1: continue
            if m & occ: continue
            if dfs(occ|m, used | (1<<idx)):
                return True
        return False
    return dfs(0,0)

print("brute independent:", brute(*case))

