from typing import List, Tuple

def brute_can_tile(n,h,w,tiles, allow_rotation=True, use_once=True):
    N=len(tiles)
    H,W=h,w
    num_cells=H*W
    full_mask=(1<<num_cells)-1 if num_cells else 0
    areas=[a*b for a,b in tiles]
    placements_by_cell=[[] for _ in range(num_cells)]
    for idx,(a,b) in enumerate(tiles):
        seen=set()
        orients={(a,b),(b,a)} if allow_rotation else {(a,b)}
        for ta,tb in orients:
            if ta>H or tb>W:
                continue
            for r in range(H-ta+1):
                for c in range(W-tb+1):
                    m=0
                    for dr in range(ta):
                        base=(r+dr)*W+c
                        for dc in range(tb):
                            cell=base+dc
                            m|=1<<cell
                    if m in seen:
                        continue
                    seen.add(m)
                    # register
                    tmp=m
                    while tmp:
                        lsb=tmp & -tmp
                        cc=(lsb.bit_length()-1)
                        placements_by_cell[cc].append((idx,m))
                        tmp ^= lsb
    import sys
    sys.setrecursionlimit(1000000)
    from functools import lru_cache
    def popcount(x): return bin(x).count("1")
    def subset_possible(rem, used):
        if rem==0:
            return True
        if use_once:
            ach=1
            for i in range(N):
                if not (used>>i)&1:
                    ach |= ach << areas[i]
            return ((ach>>rem)&1)==1
        else:
            # unlimited copies? Not handling
            return True

    @lru_cache(maxsize=None)
    def dfs(occ, used):
        if occ==full_mask:
            return True
        rem=num_cells - popcount(occ)
        if not subset_possible(rem, used):
            return False
        rembits=full_mask ^ occ
        if rembits==0:
            return False
        first=( (rembits & -rembits).bit_length()-1 )
        for idx,m in placements_by_cell[first]:
            if use_once and ((used>>idx)&1):
                continue
            # for unlimited we ignore used but then infinite loops
            if m & occ:
                continue
            if use_once:
                nxt_used = used | (1<<idx)
            else:
                nxt_used = used
            if dfs(occ|m, nxt_used):
                return True
        return False
    return dfs(0,0)

