from itertools import permutations

def min_cost_bruteforce(A,P,B,Q,W):
    best=10**18
    max_s = W//A + 5 if A!=0 else 5
    max_t = W//B + 5 if B!=0 else 5
    max_s = max(max_s, 20)
    max_t = max(max_t, 20)
    for s in range(max_s+10):
        for t in range(max_t+10):
            if s*A + t*B >= W:
                c=s*P+t*Q
                if c<best:
                    best=c
    return best

def max_cap_sum(n,X,machines, perm):
    mapped=[]
    for tup in machines:
        A=tup[perm[0]]; P=tup[perm[1]]; B=tup[perm[2]]; Q=tup[perm[3]]
        mapped.append((A,P,B,Q))
    best=0
    for W in range(30):
        total=0
        feasible=True
        for (A,P,B,Q) in mapped:
            c=min_cost_bruteforce(A,P,B,Q,W)
            total+=c
            if total>X:
                feasible=False
                break
        if feasible:
            best=W
    return best

