from itertools import combinations
from collections import deque

def is_snowflake(vertices_set, edges):
    k=len(vertices_set)
    if k<3:
        return False
    adj={v:[] for v in vertices_set}
    ecnt=0
    for u,v in edges:
        if u in vertices_set and v in vertices_set:
            adj[u].append(v)
            adj[v].append(u)
            ecnt+=1
    if ecnt != k-1:
        return False
    # connectivity
    start=next(iter(vertices_set))
    visited=set([start])
    q=deque([start])
    while q:
        cur=q.popleft()
        for nb in adj[cur]:
            if nb not in visited:
                visited.add(nb)
                q.append(nb)
    if visited!=vertices_set:
        return False
    for c in vertices_set:
        x=len(adj[c])
        if x==0:
            continue
        mids=adj[c]
        degs=[len(adj[m]) for m in mids]
        if len(set(degs))!=1:
            continue
        y=degs[0]-1
        if y<=0:
            continue
        ok=True
        leaves=set()
        for m in mids:
            for nb in adj[m]:
                if nb==c:
                    continue
                if len(adj[nb])!=1:
                    ok=False
                    break
                leaves.add(nb)
            if not ok:
                break
        if not ok:
            continue
        if len(leaves)!=x*y:
            continue
        if len(vertices_set)!=1+x+x*y:
            continue
        if vertices_set != ({c} | set(mids) | leaves):
            continue
        return True
    return False

def brute_min(n, edges):
    # iterate over all subsets via bitmask if n<=15
    best_keep=0
    best_set=None
    from itertools import combinations
    # prune by size descending
    for k in range(n,2,-1):
        for subset in combinations(range(1,n+1), k):
            s=set(subset)
            if is_snowflake(s, edges):
                return n-k, s  # maximal k first
    return n, None

