import math

def forest(b,r):
    if r==0:
        return 1 if b==0 else 0
    if b<=0 or b>r:
        return 0
    # exact integer
    from math import comb
    return b * comb(2*r - b -1, r-1)//r

def P_brute(r,k):
    s=0
    for b in range(1, k+1):
        s+= forest(b,r)
    return s

def P_formula(r,k):
    if r==0:
        return 0
    if k<=0:
        return 0
    if k>r:
        k=r
    from math import comb
    Au = comb(2*r-1, r) if 2*r-1>=r else 0
    Bu = comb(2*r-1, r+1) if 2*r-1>=r+1 else 0
    # L = 2r -k -1
    L = 2*r - k -1
    Al = comb(L, r) if L>=r and L>=0 else 0
    Bl = comb(L, r+1) if L>=r+1 and L>=0 else 0
    return (Au - Bu) - (Al - Bl)

