# brute generation for small n
def gen_polish_upto(n_max):
    from itertools import product
    generated={1:{(0,)}}
    for m in range(2, n_max+1):
        s=set()
        for k in range(1,m):
            # partitions of m-1 into k parts
            def gen_comps(rem, parts, cur):
                if parts==0:
                    if rem==0:
                        yield tuple(cur)
                    return
                for sz in range(1, rem - parts +2):
                    cur.append(sz)
                    yield from gen_comps(rem-sz, parts-1, cur)
                    cur.pop()
            for comp in gen_comps(m-1, k, []):
                lists=[generated[sz] for sz in comp]
                for prod in product(*lists):
                    seq=(k,)+ tuple(x for part in prod for x in part)
                    s.add(seq)
        generated[m]=s
    return generated

