def brute_count_leq(n,a):
    # count Polish sequences <= a lexicographically
    cnt=0
    for seq in gen[n]:
        # seq is tuple length n
        # compare lexicographically to a
        # seq <= a if lexicographically not greater
        for i in range(n):
            if seq[i] < a[i]:
                cnt+=1
                break
            elif seq[i] > a[i]:
                break
        else:
            # equal
            cnt+=1
    return cnt

# fast algorithm draft
def fast_count(n,a):
    MOD=998244353
    maxN=2*n+5
    fact=[1]*(maxN)
    for i in range(1,maxN):
        fact[i]=fact[i-1]*i%MOD
    invfact=[1]*maxN
    invfact[maxN-1]=pow(fact[maxN-1], MOD-2, MOD)
    for i in range(maxN-1,0,-1):
        invfact[i-1]=invfact[i]*i%MOD
    def binom(N,K):
        if N<0 or K<0 or K>N:
            return 0
        return fact[N]*invfact[K]%MOD*invfact[N-K]%MOD
    def P_sum(r,K):
        if K<=0 or r==0:
            return 0
        if K>r:
            K=r
        total = (binom(2*r-1, r) - binom(2*r-1, r+1)) % MOD
        sub = (binom(2*r - K -1, r) - binom(2*r - K -1, r+1)) % MOD
        return (total - sub) % MOD

    b=0
    ans=0
    for i in range(n):
        cur_a=a[i]
        r=n-i-1
        A=cur_a # number of v < cur_a
        if A>0:
            if r==0:
                if b==0:
                    # v=0 is in range if cur_a >0
                    ans = (ans+1)%MOD
            else:
                K2 = b + A -1
                K1 = b -1
                sum_val = (P_sum(r, K2) - P_sum(r, K1)) % MOD
                ans = (ans + sum_val) % MOD
        # advance for equality
        b_next = b + cur_a -1
        if r==0:
            if b_next==-1:
                ans = (ans+1)%MOD
            break
        else:
            if b_next <0:
                break
            b=b_next
    return ans % MOD

