def is_polish(seq):
    cache={}
    def polish(t):
        if t in cache:
            return cache[t]
        if len(t)==1:
            res = t[0]==0
            cache[t]=res
            return res
        if t[0]==0:
            cache[t]=False
            return False
        k=t[0]
        rem=t[1:]
        m=len(rem)
        def can_partition(start_idx, remaining):
            if remaining==0:
                return start_idx==m
            if start_idx>=m:
                return False
            for end in range(start_idx+1, m-remaining+2):
                piece=rem[start_idx:end]
                if polish(piece):
                    if can_partition(end, remaining-1):
                        return True
            return False
        res=can_partition(0,k)
        cache[t]=res
        return res
    return polish(tuple(seq))
def brute_n(n, max_val=None):
    if max_val is None:
        max_val=n-1
    import itertools
    lst=[]
    for vals in itertools.product(range(max_val+1), repeat=n):
        if is_polish(vals):
            lst.append(vals)
    return len(lst),lst
