import math
def count_distinct(x, coins):
    n=len(coins)
    total=0
    for mask in range(1,1<<n):
        l=1
        bits=0
        ok=True
        for i in range(n):
            if mask>>i &1:
                bits+=1
                g=math.gcd(l, coins[i])
                tmp=l//g
                if tmp > x // coins[i]:
                    ok=False
                    break
                l=tmp*coins[i]
        if not ok:
            continue
        if bits%2==1:
            total+= x//l
        else:
            total-= x//l
    return total
def count_multiset(x, coins):
    return sum(x//c for c in coins)
def kth_distinct(coins,k):
    lo=1
    hi= min(coins)*k
    while lo<hi:
        mid=(lo+hi)//2
        if count_distinct(mid, coins)>=k:
            hi=mid
        else:
            lo=mid+1
    return lo
def kth_multiset(coins,k):
    lo=1
    hi= min(coins)*k
    while lo<hi:
        mid=(lo+hi)//2
        if count_multiset(mid, coins)>=k:
            hi=mid
        else:
            lo=mid+1
    return lo

