def brute_H(W,H,L,R,D,U):
    h=[[0]*(H+1) for _ in range(W+1)]
    for x in range(W+1):
        for y in range(H+1):
            if L <= x <= R and D <= y <= U:
                h[x][y]=1
            else:
                left = h[x-1][y] if x-1>=0 else 1
