    for n,s in cases:
        a=brute_count(n,s)
        b=forests(n,s)
        assert False, f"{n} {s} indeg={a} forest={b}"

def brute_count(n,s):
    edges=[]
    for i in range(n):
        edges.append((i,(i+1)%n))
    for i,ch in enumerate(s):
        if ch=='1':
            edges.append((i,n))
    m=len(edges)
    seen=set()
    for mask in range(1<<m):
        d=[0]*(n+1)
        for e_idx,(u,v) in enumerate(edges):
            bit=(mask>>e_idx)&1
            if bit==0:
                d[v]+=1
            else:
                d[u]+=1
        seen.add(tuple(d))
    return len(seen)

def forests(n,s):
    edges=[]
    for i in range(n):
        edges.append((i,(i+1)%n))
    for i,ch in enumerate(s):
        if ch=='1':
            edges.append((i,n))
    m=len(edges)
    def is_forest(mask):
        parent=list(range(n+1))
        def find(x):
            while parent[x]!=x:
                parent[x]=parent[parent[x]]
                x=parent[x]
            return x
        def union(a,b):
            ra=find(a); rb=find(b)
            if ra==rb:
                return False
            parent[rb]=ra
            return True
        for e_idx,(u,v) in enumerate(edges):
            if (mask>>e_idx)&1:
                if not union(u,v):
                    return False
        return True
    cnt=0
    for mask in range(1<<m):
        if is_forest(mask):
            cnt+=1
    return cnt

