                is_p = False
                break
        if is_p:
            primes.append(p)
    r = len(primes)
    d = 1 << r

    # exponents for each a in 1..m
    exps_list = []
    for a in range(1, m + 1):
        tmp = a
        e = [0] * r
        for i, pr in enumerate(primes):
            cnt = 0
            while tmp % pr == 0:
                tmp //= pr
                cnt += 1
            e[i] = cnt
        exps_list.append(e)

    O = [0] * d
    for mask in range(d):
        total = 0
        for e in exps_list:
            prod = 1
            mm = mask
            # iterate bits of mask
            # early break if any required exponent zero
            for j in range(r):
                if (mask >> j) & 1:
                    if e[j] == 0:
                        prod = 0
                        break
                    prod *= e[j]
            total += prod
        O[mask] = total % MOD

    # precompute subsets for each mask
    subsets = [[] for _ in range(d)]
    for S in range(d):
        sub = S
        lst = []
        while True:
            lst.append(sub)
            if sub == 0:
                break
            sub = (sub - 1) & S
        subsets[S] = lst

    # matrix M[S][T] = O[S ^ T] if T subset S
    M = [[0] * d for _ in range(d)]
    for S in range(d):
        for T in subsets[S]:
            diff = S ^ T  # == S & ~T
            M[S][T] = O[diff]

    # helper functions closing over d, MOD, subsets
    def mat_vec_mul(mat, vec):
        res = [0] * d
        for S in range(d):
            tot = 0
            for T in subsets[S]:
                vt = vec[T]
                if vt:
                    tot = (tot + mat[S][T] * vt) % MOD
            res[S] = tot
        return res

    def mat_mat_mul(A, B):
        C = [[0] * d for _ in range(d)]
        for S in range(d):
            for U in subsets[S]:
                a = A[S][U]
                if a == 0:
                    continue
                # B[U][T] non-zero only for T subset U
                for T in subsets[U]:
                    b = B[U][T]
                    if b == 0:
                        continue
                    C[S][T] = (C[S][T] + a * b) % MOD
        return C

    # identity
    I_mat = [[0] * d for _ in range(d)]
    for i in range(d):
        I_mat[i][i] = 1

    max_log = n.bit_length()
    powM = [None] * max_log
    vec_sum = [None] * max_log

    powM[0] = M
    v0 = [0] * d
    v0[0] = 1
    vec_sum[0] = mat_vec_mul(M, v0)  # = O

    for k in range(1, max_log):
        powM[k] = mat_mat_mul(powM[k - 1], powM[k - 1])
        tmp = mat_vec_mul(powM[k - 1], vec_sum[k - 1])
        cur = [0] * d
        prev = vec_sum[k - 1]
        for i in range(d):
            cur[i] = (prev[i] + tmp[i]) % MOD
        vec_sum[k] = cur

    ans_vec = [0] * d
    cur_pow = I_mat

    for k in range(max_log):
        if (n >> k) & 1:
            contrib = mat_vec_mul(cur_pow, vec_sum[k])
            for i in range(d):
                ans_vec[i] = (ans_vec[i] + contrib[i]) % MOD
            cur_pow = mat_mat_mul(cur_pow, powM[k])

    total = sum(ans_vec) % MOD
    return total

