from typing import List
import functools

WIN_LINES = [
    0b000000111, # row0: cells 0,1,2
    0b000111000, # row1: 3,4,5
    0b111000000, # row2: 6,7,8
    0b001001001, # col0: 0,3,6
    0b010010010, # col1: 1,4,7
    0b100100100, # col2: 2,5,8
    0b100010001, # diag 0,4,8
    0b001010100, # diag 2,4,6
]

def has_line(mask):
    for line in WIN_LINES:
        if (mask & line) == line:
            return True
    return False

def tic_tac_toe_winner_bruteforce(grid):
    vals = [grid[r][c] for r in range(3) for c in range(3)]
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def can_T_win(mask_T, mask_A, turn): # turn 0 = Takahashi to move
        occupied = mask_T | mask_A
        empty = [i for i in range(9) if not (occupied >> i) & 1]
        if not empty:
            score_T = 0
            for i in range(9):
                if (mask_T >> i) & 1:
                    score_T += vals[i]
            score_A = 0
            for i in range(9):
                if (mask_A >> i) & 1:
                    score_A += vals[i]
            return score_T > score_A
        if turn == 0: # Takahashi
            # try all moves
            for i in empty:
                new_T = mask_T | (1 << i)
                if has_line(new_T):
                    return True
            # no immediate winning line, try recursion
            for i in empty:
                new_T = mask_T | (1 << i)
                # we already know no immediate win for those i, but loop again to check recursive win
                # Actually if immediate win existed we already returned, so we could have returned True already.
                # But to keep logic split, we do:
                # If we are here, no immediate win, so explore
                if can_T_win(new_T, mask_A, 1):
                    return True
            return False
        else: # Aoki
            for i in empty:
                new_A = mask_A | (1 << i)
                if has_line(new_A):
                    return False
            for i in empty:
                new_A = mask_A | (1 << i)
                if not can_T_win(mask_T, new_A, 0):
                    # Aoki found a move that makes Takahashi lose
                    return False
            # If all moves lead to Takahashi win, then Takahashi wins
            return True

    # But this split logic is flawed: we return True for Takahashi immediate win before checking if Aoki could win? No, at Takahashi turn we check his immediate win correctly.
    # However for efficiency we separated loops; but correct logic should be: for each move, check immediate win else recurse.
    # The above double-loop for Takahashi incorrectly returns True if any immediate win exists, which is correct, but second loop checking recursive wins is incomplete because we excluded immediate wins already but that's fine.
    # For Aoki we did similar: first check if any immediate win exists -> return False immediately. Then second loop check if exists move causing Takahashi loss.
    # That's correct but we can combine.

    # Let's implement combined properly for validation:
    @lru_cache(maxsize=None)
    def can_T_win2(mask_T, mask_A, turn):
        occupied = mask_T | mask_A
        empty = [i for i in range(9) if not (occupied >> i) & 1]
        if not empty:
            score_T = sum(vals[i] for i in range(9) if (mask_T >> i) & 1)
            score_A = sum(vals[i] for i in range(9) if (mask_A >> i) & 1)
            return score_T > score_A
        if turn == 0:
            for i in empty:
                new_T = mask_T | (1 << i)
                if has_line(new_T):
                    return True
                if can_T_win2(new_T, mask_A, 1):
                    return True
            return False
        else:
            for i in empty:
                new_A = mask_A | (1 << i)
                if has_line(new_A):
                    return False
                if not can_T_win2(mask_T, new_A, 0):
                    return False
            return True

    result = can_T_win2(0,0,0)
    return "Takahashi" if result else "Aoki"

