    # Build SCC condensation adj for reachability
    # scc_adj matrix
    scc_adj = [[False]*num_scc for _ in range(num_scc)]
    for i in range(num_scc):
        scc_adj[i][i]=True
    for tail_scc, head_scc in inter_edges:
        scc_adj[tail_scc][head_scc]=True
    # Floyd-Warshall transitive closure
    for k in range(num_scc):
        for i in range(num_scc):
            if scc_adj[i][k]:
                row_k = scc_adj[k]
                row_i = scc_adj[i]
                # if i->k and k->j then i->j
                for j in range(num_scc):
                    if row_k[j]:
