    adj = [[] for _ in range(m)]
    for i in range(m):
        head_i = q_nodes[i][1]
        # for each j, check if head_i can reach tail_j
        for j in range(m):
            if i == j:
                continue
            tail_j = q_nodes[j][0]
            if scc_adj[head_i][tail_j]:
                adj[i].append(j)
    # Hopcroft-Karp
    pair_u = [-1]*m
    pair_v = [-1]*m
    dist = [0]*m
    INF = 10**9
    def bfs():
        q = deque()
        for u in range(m):
            if pair_u[u]==-1:
                dist[u]=0
                q.append(u)
            else:
                dist[u]=INF
        d_augment = INF
        while q:
            u = q.popleft()
            if dist[u] < d_augment:
                for v in adj[u]:
                    pu = pair_v[v]
                    if pu == -1:
                        d_augment = dist[u]+1
                    else:
                        if dist[pu]==INF:
                            dist[pu]=dist[u]+1
                            q.append(pu)
        # return whether found augmenting path
        # We will use standard BFS layering; in DFS we need to know if we can reach free vertex
        # For simplicity, return True if any free vertex reachable
        return d_augment != INF
    # DFS with recursion may be heavy, use iterative stack
    sys_set = False
    import sys
    sys.setrecursionlimit(10000)
    def dfs(u):
        for v in adj[u]:
            pu = pair_v[v]
            if pu == -1 or (dist[pu]==dist[u]+1 and dfs(pu)):
                pair_u[u]=v
                pair_v[v]=u
                return True
        dist[u]=INF
        return False
    matching = 0
    while bfs():
        for u in range(m):
            if pair_u[u]==-1:
                if dfs(u):
                    matching+=1
    return m - matching

