        rev = [fr, 0, fwd]
        fwd[2] = rev
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def bfs_level(self, s, t, level):
        q = deque([s])
        level[:] = [-1] * self.n
        level[s] = 0
        while q:
            v = q.popleft()
            for to, cap, rev in self.g[v]:
                if cap > 0 and level[to] < 0:
                    level[to] = level[v] + 1
                    q.append(to)
        return level[t] != -1

    def dfs(self, v, t, f, level, it):
        if v == t:
            return f
        for i in range(it[v], len(self.g[v])):
            it[v] = i
            to, cap, rev = self.g[v][i]
            if cap > 0 and level[v] < level[to]:
                ret = self.dfs(to, t, min(f, cap), level, it)
                if ret:
                    self.g[v][i][1] -= ret
                    rev[1] += ret
                    return ret
        return 0

    def max_flow(self, s, t, limit=None):
        flow = 0
        level = [0] * self.n
        while self.bfs_level(s, t, level):
            it = [0] * self.n
            while True:
                pushed = self.dfs(s, t, 10 ** 18, level, it)
                if not pushed:
                    break
                flow += pushed
                if flow >= INF:
                    return flow
                if limit is not None and flow > limit:
                    return flow
        return flow


def bfs_hop(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
    dist = [-1] * (n + 1)
    dist[1] = 0
    q = deque([1])
    while q:
        u = q.popleft()
        for w in adj[u]:
            if dist[w] == -1:
                dist[w] = dist[u] + 1
                q.append(w)
    return dist[n]


def min_cut_cost(n, edges, L):
    if L == 0:
        return 0
    N = n
    LOW = -N
    HIGH = N + 1
    T = list(range(LOW, HIGH + 1))
    num_T = len(T)
    # map threshold value -> index not needed, we iterate by index

    def node_id(v, ti):
        return (v - 1) * num_T + ti

    total = n * num_T + 2
    SRC = total - 2
    SNK = total - 1
    dinic = Dinic(total)

    # monotonic edges (v, t') -> (v, t) for t' = t+1
    for v in range(1, n + 1):
        for ti in range(1, num_T):
            dinic.add_edge(node_id(v, ti), node_id(v, ti - 1), INF)

    # edges for original graph: cost and feasibility
    for (u, v) in edges:
        for ti in range(num_T):
            # cost edge (v,t) -> (u,t) cap 1
            dinic.add_edge(node_id(v, ti), node_id(u, ti), 1)
        for ti in range(1, num_T):
            # feasibility (v, t_next) -> (u, t_prev) INF
            dinic.add_edge(node_id(v, ti), node_id(u, ti - 1), INF)

    # force extremes to avoid truncation exploit
    low_ti = 0
    high_ti = num_T - 1
    for v in range(1, n + 1):
        dinic.add_edge(SRC, node_id(v, low_ti), INF)
        dinic.add_edge(node_id(v, high_ti), SNK, INF)

    # pinning for source 1 and sink n
    for ti, t in enumerate(T):
        nid1 = node_id(1, ti)
        if t <= 0:
            dinic.add_edge(SRC, nid1, INF)
        else:
            dinic.add_edge(nid1, SNK, INF)
        nidn = node_id(n, ti)
        if t <= L:
            dinic.add_edge(SRC, nidn, INF)
        else:
            dinic.add_edge(nidn, SNK, INF)

    flow = dinic.max_flow(SRC, SNK)
    return flow


def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    """ Given a directed graph with n vertices (numbered 1 to n) and m edges, where initially
    all edges have weight 0. You can choose exactly k edges and change their weights to 1.
    Find the maximum possible shortest distance from vertex 1 to vertex n after this operation.
    """
    hop = bfs_hop(n, edges)
    if hop == -1:
        # fallback (should not happen)
        hop = n  # maximal feasible could be n maybe
    # cap hop to n (max simple path)
    # also maximal distance cannot exceed k (since each edge weight at most 1)
    # but we let cut decide
    # monotone: if L feasible then all smaller feasible
    best = 0
    # binary search could be used, but linear is fine (hop <=30)
    for L in range(hop + 1):
        c = min_cut_cost(n, edges, L)
        if c <= k:
            best = L
        else:
            # if infeasible due to >k or INF, larger L will be also infeasible (cost non-decreasing)
            # we could continue to verify but we know monotonic
            # To keep correctness even if non-monotonic due to bug, we continue
            pass
    return best

